 function v49PurchasePaymentAccountOptions(unitId){return (db.financialAccounts||[]).filter(a=>a.active!==false&&(!unitId||a.unitId===unitId)&&a.type!=='PROCESSOR').map(a=>`<option value="${a.id}">${escapeHtml(a.name)} · ${escapeHtml(financeUnitLabel(a.unitId))}</option>`).join('')}
 function openStockPurchasePayment(id){let p=db.stockPurchases.find(x=>x.id===id);if(!p||p.financeStatus==='Pago')return;let unitId=v49PurchaseFinanceUnit(p),opts=v49PurchasePaymentAccountOptions(unitId);if(!opts){toast('Cadastre uma conta bancária/caixa para a unidade responsável antes de pagar');return}modal(`Pagar compra · ${p.supplier}`,`<div class="inline-note"><b>Obrigação:</b> ${money(p.total)} · compra de ${formatDateBR(p.date)}.<br>O custo permanece capitalizado no estoque. Este pagamento apenas baixa a obrigação e movimenta a conta escolhida.</div><div class="form-grid" style="margin-top:12px"><div class="field"><label>Data do pagamento</label><input id="stkBuyPayDate" type="date" value="${localDateISO()}"></div><div class="field"><label>Unidade responsável</label><input value="${escapeAttr(financeUnitLabel(unitId)||'Não informada')}" disabled></div><div class="field full"><label>Conta de saída</label><select id="stkBuyPayAccount">${opts}</select></div><div class="field full"><label>Observação</label><input id="stkBuyPayNote" placeholder="Opcional"></div></div>`,`<button class="btn btn-ghost" onclick="closeModal();openStockPurchaseDetail('${id}')">Voltar</button><button class="btn btn-primary" onclick="saveStockPurchasePayment('${id}')">Confirmar pagamento</button>`)}
 function saveStockPurchasePayment(id){let p=db.stockPurchases.find(x=>x.id===id);if(!p||p.financeStatus==='Pago'){toast('Esta compra já está paga');return}let entry=v49EnsurePurchasePayable(p),accountId=document.getElementById('stkBuyPayAccount')?.value||'',acc=db.financialAccounts.find(a=>a.id===accountId),date=document.getElementById('stkBuyPayDate')?.value||localDateISO();if(!acc){toast('Selecione a conta de saída');return}entry.originalDate=entry.originalDate||p.date;entry.date=date;entry.status='Efetivado';entry.accountId=acc.id;entry.account=acc.name;entry.paidAt=new Date().toISOString();entry.paidBy=currentUserName();entry.note=document.getElementById('stkBuyPayNote')?.value.trim()||'';entry.unitId=v49PurchaseFinanceUnit(p)||acc.unitId||'';p.financeStatus='Pago';p.paidDate=date;p.paidAccountId=acc.id;p.paidAccountName=acc.name;p.paidAt=entry.paidAt;p.paidBy=entry.paidBy;save();closeModal();renderStockPurchases();toast('Compra paga · obrigação financeira baixada sem novo custo no DRE ✓')}
 const _openStockPurchaseDetailV49Base=openStockPurchaseDetail;
 openStockPurchaseDetail=function(id){_openStockPurchaseDetailV49Base(id);let p=db.stockPurchases.find(x=>x.id===id),foot=document.querySelector('#modalHost .modal-foot'),body=document.querySelector('#modalHost .modal-body');if(body&&p){let e=v49PurchasePayable(p),box=document.createElement('div');box.className='inline-note';box.style.marginTop='12px';box.innerHTML=`<b>Financeiro:</b> ${p.financeStatus==='Pago'?`Pago em ${formatDateBR(p.paidDate)} por ${escapeHtml(p.paidAccountName||'conta registrada')}`:`Obrigação de ${money(p.total)} em aberto${v49PurchaseFinanceUnit(p)?' · '+escapeHtml(financeUnitLabel(v49PurchaseFinanceUnit(p))):' · unidade financeira não informada'}`}${e?' · origem rastreada no Financeiro':''}.`;body.appendChild(box)}if(foot&&p?.financeStatus!=='Pago')foot.insertAdjacentHTML('afterbegin',`<button class="btn btn-soft" onclick="closeModal();openStockPurchasePayment('${id}')">Pagar compra</button>`)};
 
 // 10) Recebimento de Conta Mensal preserva a unidade de origem do recebível e a unidade da conta que recebeu o dinheiro.
 const _saveClientMonthlySettlementV49Base=saveClientMonthlySettlement;
 saveClientMonthlySettlement=function(id){let p0=(db.clientReceivablePayments||[]).length,c0=(db.demoCashMovements||[]).length,f0=(db.demoFinancialEntries||[]).length,accountId=document.getElementById('cmPayAccount')?.value||'',acc=db.financialAccounts.find(a=>a.id===accountId);_saveClientMonthlySettlementV49Base(id);let pay=(db.clientReceivablePayments||[])[p0];if(!pay)return;pay.accountUnitId=acc?.unitId||'';pay.sourceType='client_receivable_settlement';for(const x of (db.demoCashMovements||[]).slice(c0)){x.accountId=accountId;x.accountUnitId=acc?.unitId||'';x.receivableSourceUnitId=x.unitId;x.sourceType='client_receivable_settlement';x.sourceId=pay.id}for(const x of (db.demoFinancialEntries||[]).slice(f0)){x.accountId=accountId;x.accountUnitId=acc?.unitId||'';x.receivableSourceUnitId=x.unitId;x.sourceType='client_receivable_settlement';x.sourceId=pay.id}save()};
 
 // 11) Renomear conta não reescreve o fato histórico; o saldo considera aliases antigos.
 // financeAccountBalance é mantida pela implementação canônica baseada em financeOperationalLedgerEntries().
 financeFilteredEntries=function(state=financeFiltersState()){return financeSyntheticEntries().filter(e=>{if(state.from&&String(e.date||'')<state.from)return false;if(state.to&&String(e.date||'')>state.to)return false;if(state.unit&&state.unit!=='all'&&e.unitId!==state.unit)return false;if(state.account){let a=(db.financialAccounts||[]).find(x=>x.name===state.account||x.id===state.account);if(a){let names=new Set([a.name,...(a.previousNames||[])]);if(!((e.accountId&&e.accountId===a.id)||(!e.accountId&&names.has(e.account))))return false}else if(e.account!==state.account)return false}if(state.q&&!`${e.nature||''} ${e.category||''} ${e.account||''} ${e.origin||''} ${e.professionalName||''}`.toLowerCase().includes(state.q))return false;return true})};
 saveFinanceAccount=function(id){let a=db.financialAccounts.find(x=>x.id===id);if(!a)return;let oldName=a.name,name=document.getElementById('finAccName')?.value.trim()||'';if(!name){toast('Informe o nome da conta');return}let unitId=document.getElementById('finAccUnit')?.value||a.unitId;if(!(db.units||[]).some(u=>u.id===unitId)){toast('Selecione uma unidade válida');return}if(db.financialAccounts.some(x=>x.id!==id&&x.unitId===unitId&&String(x.name||'').toLowerCase()===name.toLowerCase())){toast('Já existe uma conta com esse nome nesta unidade');return}let companyId=document.getElementById('finAccCompany')?.value??a.companyEntityId??'';if(companyId){let c=typeof companyById==='function'?companyById(companyId):(db.companyEntities||[]).find(x=>x.id===companyId);if(!c||c.unitId!==unitId){toast('O CNPJ selecionado não pertence a esta unidade');return}}if(oldName!==name){a.previousNames=Array.isArray(a.previousNames)?a.previousNames:[];if(oldName&&!a.previousNames.includes(oldName))a.previousNames.push(oldName)}a.name=name;a.unitId=unitId;a.companyEntityId=companyId;a.type=document.getElementById('finAccType')?.value||a.type;a.active=!!document.getElementById('finAccActive')?.checked;a.details=a.details||{};a.details.institution=document.getElementById('finAccInstitution')?.value.trim()||'';a.details.internalCode=document.getElementById('finAccInternal')?.value.trim()||'';if(document.getElementById('finAccOpeningBalance'))a.openingBalance=roundMoney(Number(document.getElementById('finAccOpeningBalance')?.value||0));if(document.getElementById('finAccOpeningDate'))a.openingBalanceDate=document.getElementById('finAccOpeningDate')?.value||a.openingBalanceDate||financeToday;a.paymentMethodIds=[...document.querySelectorAll('.fin-acc-method:checked')].map(x=>x.value);a.feeRules=a.feeRules||{};for(const mid of a.paymentMethodIds){let pct=document.querySelector(`.fin-rule-percent[data-mid="${mid}"]`),fixed=document.querySelector(`.fin-rule-fixed[data-mid="${mid}"]`),days=document.querySelector(`.fin-rule-days[data-mid="${mid}"]`);a.feeRules[mid]={percent:Math.max(0,Number(pct?.value||0)),fixed:roundMoney(Math.max(0,Number(fixed?.value||0))),settlementDays:Math.max(0,Math.round(Number(days?.value||0)))}}save();closeModal();renderFinanceAccounts();toast('Conta financeira atualizada · histórico preservado ✓')};
 
 // 12) Migração V49 idempotente: preserva localStorage e arquiva apropriações antigas geradas por transferência.
 function v49BackfillAccountId(x){if(!x||x.accountId||!x.account)return;let matches=(db.financialAccounts||[]).filter(a=>a.name===x.account&&(!x.unitId||a.unitId===x.unitId));if(matches.length===1)x.accountId=matches[0].id}
 function v49TagHistoricalCommandSources(){for(const c of (db.clientCommands||[]).filter(c=>c.status==='Pago')){if(!c.finalizationEventId)c.finalizationEventId=`legacy:${c.id}`;let code=String(c.id).replace(/\D/g,'');for(const x of (db.demoCashMovements||[]).filter(x=>x.commandId===c.id)){x.sourceEventId=x.sourceEventId||c.finalizationEventId;x.sourceType=x.sourceType||'command_finalization';x.sourceId=x.sourceId||c.id;v49BackfillAccountId(x)}for(const x of (db.tipMovements||[]).filter(x=>x.commandId===c.id)){x.sourceEventId=x.sourceEventId||c.finalizationEventId;x.sourceType=x.sourceType||'command_tip';x.sourceId=x.sourceId||c.id}for(const x of (db.demoFinancialEntries||[]).filter(x=>x.commandId===c.id||x.origin===`Comanda #${code}`)){x.sourceEventId=x.sourceEventId||c.finalizationEventId;x.sourceType=x.sourceType||(String(x.nature||'').toLowerCase().includes('gorjeta')?'command_tip':'command_finalization');x.sourceId=x.sourceId||c.id;v49BackfillAccountId(x)}for(const x of (db.stockMovements||[]).filter(x=>x.refId===c.id||x.sourceId===c.id)){x.sourceEventId=x.sourceEventId||c.finalizationEventId;x.sourceType=x.sourceType||'command_stock';x.sourceId=x.sourceId||c.id}}for(const x of (db.demoCashMovements||[]))v49BackfillAccountId(x);for(const x of (db.demoFinancialEntries||[]))v49BackfillAccountId(x)}
 function v49Migrate(){let current=Number(db.schemaVersion||0),changed=false;db.v49MigrationArchive=db.v49MigrationArchive||{};if(current<V49_SCHEMA){let transferCosts=(db.stockInputCosts||[]).filter(x=>x.transferId);if(transferCosts.length){db.v49MigrationArchive.stockInputCostsFromTransfers=structuredClone(transferCosts);db.stockInputCosts=(db.stockInputCosts||[]).filter(x=>!x.transferId);changed=true}v49TagHistoricalCommandSources();for(const c of (db.clientCommands||[]).filter(c=>c.status==='Pago'))v49BuildCommissionEventsForCommand(c,{legacy:true});for(const p of (db.stockPurchases||[])){if(!p.financeUnitId&&p.destinationId&&p.destinationId!=='central'){p.financeUnitId=p.destinationId;changed=true}if(p.financeStatus!=='Pago'&&!v49PurchasePayable(p)){v49EnsurePurchasePayable(p);changed=true}}db.schemaVersion=V49_SCHEMA;db.schemaMigratedAt=new Date().toISOString();changed=true}if(changed)save({render:false})}
 v49Migrate();cashDate=localDateISO();
 
